using System;
using System.Collections.Generic;
using UnityEngine;
namespace HarborValeGreybox.Workshop {
public sealed class WorkshopPartPreview:IDisposable {
 GameObject root,model;Camera camera;RenderTexture texture;float lastRender=-1,radius;readonly List<Material> materials=new List<Material>();readonly List<Mesh> meshes=new List<Mesh>();Material metal,dark,rubber,accent,red,blue;
 public string SelectedId{get;private set;}public int MeshCount=>model==null?0:model.GetComponentsInChildren<MeshFilter>().Length;
 Material Mat(Color c,float metallic=0){var m=new Material(Shader.Find("Standard")){color=c};m.SetFloat("_Metallic",metallic);m.SetFloat("_Glossiness",.35f);materials.Add(m);return m;}
 void Create(){root=new GameObject("Workshop selected part | preview only");root.transform.position=new Vector3(0,-1200,0);metal=Mat(new Color(.65f,.70f,.73f),.75f);dark=Mat(new Color(.12f,.17f,.20f),.4f);rubber=Mat(new Color(.065f,.07f,.075f));accent=Mat(new Color(.15f,.8f,.68f),.35f);red=Mat(new Color(.72f,.16f,.12f),.2f);blue=Mat(new Color(.15f,.35f,.7f),.4f);camera=new GameObject("Part preview camera").AddComponent<Camera>();camera.transform.SetParent(root.transform,false);camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.045f,.07f,.1f);camera.fieldOfView=36;camera.nearClipPlane=.03f;camera.farClipPlane=40;camera.enabled=false;texture=new RenderTexture(480,180,16){name="Selected part preview"};texture.Create();camera.targetTexture=texture;var light=new GameObject("Part preview fill").AddComponent<Light>();light.transform.SetParent(root.transform,false);light.transform.localPosition=new Vector3(1,2,2);light.type=LightType.Point;light.range=10;light.intensity=2;light.cullingMask=1<<31;light.shadows=LightShadows.None;}
 GameObject Shape(PrimitiveType kind,string name,Vector3 position,Vector3 scale,Material material,Vector3 rotation=default){var g=GameObject.CreatePrimitive(kind);g.name=name;g.layer=31;g.transform.SetParent(model.transform,false);g.transform.localPosition=position;g.transform.localScale=scale;g.transform.localRotation=Quaternion.Euler(rotation);var c=g.GetComponent<Collider>();if(c!=null){c.enabled=false;UnityEngine.Object.Destroy(c);}g.GetComponent<Renderer>().sharedMaterial=material;return g;}
 void Box(string name,Vector3 p,Vector3 size,Material m)=>Shape(PrimitiveType.Cube,name,p,size,m);
 void Cylinder(string name,Vector3 p,float diameter,float length,Material m,Vector3 rotation=default)=>Shape(PrimitiveType.Cylinder,name,p,new Vector3(diameter,length/2,diameter),m,rotation);
 void Ring(string name,Vector3 p,float major,float minor,Material material,Vector3 rotation=default){const int around=24,tube=8;var v=new Vector3[(around+1)*(tube+1)];var t=new List<int>();for(int i=0;i<=around;i++)for(int j=0;j<=tube;j++){float a=i*2*Mathf.PI/around,b=j*2*Mathf.PI/tube;v[i*(tube+1)+j]=new Vector3((major+minor*Mathf.Cos(b))*Mathf.Cos(a),(major+minor*Mathf.Cos(b))*Mathf.Sin(a),minor*Mathf.Sin(b));if(i<around&&j<tube){int q=i*(tube+1)+j;t.AddRange(new[]{q,q+tube+1,q+1,q+1,q+tube+1,q+tube+2});}}var mesh=new Mesh{name=name,vertices=v,triangles=t.ToArray()};mesh.RecalculateNormals();mesh.RecalculateBounds();meshes.Add(mesh);var g=new GameObject(name);g.layer=31;g.transform.SetParent(model.transform,false);g.transform.localPosition=p;g.transform.localRotation=Quaternion.Euler(rotation);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;}
 void Turbo(Vector3 p,float size){Ring("Compressor housing",p,.24f*size,.10f*size,metal);Cylinder("Compressor inlet",p+Vector3.forward*.12f,.25f*size,.18f*size,dark,new Vector3(90,0,0));Cylinder("Turbine",p+Vector3.back*.25f,.36f*size,.25f*size,dark,new Vector3(90,0,0));Box("Outlet",p+new Vector3(.22f,.2f,0)*size,new Vector3(.25f,.12f,.12f)*size,metal);}
 void Build(WorkshopOffer offer){if(model!=null){model.SetActive(false);UnityEngine.Object.Destroy(model);}foreach(var mesh in meshes)UnityEngine.Object.Destroy(mesh);meshes.Clear();model=new GameObject("Part shape | "+offer.id);model.transform.SetParent(root.transform,false);float stage=1+.08f*Mathf.Max(0,offer.stage-1);
  switch(offer.slot){
   case "induction":if(offer.choice=="roots"){Box("Blower case",Vector3.zero,new Vector3(.85f,.4f,.45f),metal);for(int i=-2;i<=2;i++)Box("Case rib",new Vector3(i*.15f,.21f,0),new Vector3(.04f,.035f,.5f),dark);Ring("Drive pulley",new Vector3(.55f,0,0),.19f,.04f,dark,new Vector3(0,90,0));}else if(offer.choice=="twin"){Turbo(new Vector3(-.42f,0,0),.85f);Turbo(new Vector3(.42f,0,0),.85f);}else if(offer.choice=="none"){Box("Original intake",Vector3.zero,new Vector3(.6f,.35f,.4f),dark);}else Turbo(Vector3.zero,stage*(offer.choice=="large"?1.25f:1));break;
   case "tirecompound":case "tires":Ring("Rubber tire",Vector3.zero,.36f,.14f,rubber);Ring("Wheel rim",Vector3.zero,.24f,.035f,metal);Cylinder("Wheel hub",Vector3.zero,.12f,.16f,metal,new Vector3(90,0,0));for(int i=0;i<5;i++){float a=i*72*Mathf.Deg2Rad;var spoke=Shape(PrimitiveType.Cube,"Spoke",new Vector3(Mathf.Cos(a)*.13f,Mathf.Sin(a)*.13f,0),new Vector3(.28f,.035f,.04f),metal);spoke.transform.localRotation=Quaternion.Euler(0,0,i*72);}if(offer.choice!="slick")for(int i=0;i<16;i++){float a=i*2*Mathf.PI/16;Shape(PrimitiveType.Cube,"Tread",new Vector3(Mathf.Cos(a)*.5f,Mathf.Sin(a)*.5f,0),new Vector3(.035f,.015f,.13f),dark,new Vector3(0,0,i*22.5f));}break;
   case "drivetrain":Box("Chassis reference",Vector3.zero,new Vector3(.06f,.06f,1.8f),dark);foreach(float z in new[]{-.7f,.7f}){bool driven=offer.choice=="awd"||(z>0?offer.choice=="fwd":offer.choice=="rwd");Box("Axle",new Vector3(0,0,z),new Vector3(1.6f,.07f,.07f),driven?accent:dark);foreach(float x in new[]{-.9f,.9f})Shape(PrimitiveType.Cube,"Wheel",new Vector3(x,0,z),new Vector3(.2f,.4f,.4f),rubber);}if(offer.choice!="fwd")Box("Propeller shaft",Vector3.zero,new Vector3(.10f,.10f,1.4f),accent);break;
   case "cooling":Box("Intercooler core",Vector3.zero,new Vector3(1.2f,.55f,.18f),metal);for(int i=-5;i<=5;i++)Box("Cooling fin",new Vector3(i*.09f,0,.1f),new Vector3(.025f,.50f,.02f),dark);Box("End tank",new Vector3(.68f,0,0),new Vector3(.16f,.6f,.22f),dark);Box("End tank",new Vector3(-.68f,0,0),new Vector3(.16f,.6f,.22f),dark);break;
   case "brakes":Cylinder("Rotor",Vector3.zero,.8f,.06f,metal,new Vector3(90,0,0));Ring("Rotor rim",Vector3.zero,.35f,.025f,dark);Cylinder("Hub",Vector3.forward*.04f,.20f,.10f,dark,new Vector3(90,0,0));Box("Caliper",new Vector3(.34f,0,.05f),new Vector3(.24f,.36f,.18f),red);break;
   case "suspension":Cylinder("Damper",Vector3.zero,.12f,1.2f,metal);for(int i=0;i<7;i++)Ring("Spring coil",new Vector3(0,-.4f+i*.13f,0),.19f,.035f,red,new Vector3(90,0,0));break;
   case "aero":Box("Wing",new Vector3(0,.3f,0),new Vector3(1.6f,.07f,.35f),dark);foreach(float x in new[]{-.5f,.5f})Box("Upright",new Vector3(x,0,0),new Vector3(.06f,.6f,.15f),metal);break;
   case "intake":Cylinder("Filter",Vector3.zero,.5f,.5f,red,new Vector3(0,0,90));Cylinder("Intake tube",new Vector3(.5f,0,0),.2f,.65f,metal,new Vector3(0,0,90));break;
   case "exhaust":case "sound":Cylinder("Muffler",Vector3.zero,.4f,.8f,metal,new Vector3(0,0,90));foreach(float x in new[]{-.6f,.6f})Cylinder("Exhaust pipe",new Vector3(x,0,0),.13f,.4f,dark,new Vector3(0,0,90));break;
   case "na":Box("Engine block",Vector3.zero,new Vector3(.8f,.5f,.6f),dark);for(int i=0;i<4;i++)Cylinder("Cylinder",new Vector3(-.3f+i*.2f,.3f,0),.16f,.2f,metal);Box("Calibration module",new Vector3(.6f,0,0),new Vector3(.28f,.1f,.35f),blue);break;
   default:Box("Transmission housing",Vector3.zero,new Vector3(.65f,.5f,.5f),metal);Cylinder("Shaft",Vector3.zero,.12f,1.4f,dark,new Vector3(0,0,90));Ring("Gear",new Vector3(.4f,0,0),.3f,.055f,accent,new Vector3(0,90,0));break;
  }
  var renderers=model.GetComponentsInChildren<Renderer>();Bounds bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);radius=bounds.extents.magnitude;var center=bounds.center-root.transform.position;foreach(Transform child in model.transform)child.localPosition-=center;camera.transform.localPosition=new Vector3(1.4f,.9f,2.5f).normalized*Mathf.Max(.5f,radius)*3.4f;camera.transform.LookAt(root.transform.position);SelectedId=offer.id;lastRender=-1;
 }
 public void Draw(Rect rect,WorkshopOffer offer){if(offer==null){GUI.Label(rect,"Select a part");return;}if(root==null)Create();if(SelectedId!=offer.id)Build(offer);if(Event.current.type==EventType.Repaint&&Time.unscaledTime-lastRender>.04f){lastRender=Time.unscaledTime;model.transform.localRotation=Quaternion.Euler(0,Time.unscaledTime*16,0);camera.Render();}GUI.DrawTexture(rect,texture,ScaleMode.ScaleToFit,false);}
 public void Dispose(){if(camera!=null)camera.targetTexture=null;if(root!=null)UnityEngine.Object.Destroy(root);foreach(var m in materials)UnityEngine.Object.Destroy(m);foreach(var m in meshes)UnityEngine.Object.Destroy(m);materials.Clear();meshes.Clear();if(texture!=null){texture.Release();UnityEngine.Object.Destroy(texture);}root=null;model=null;camera=null;texture=null;SelectedId=null;lastRender=-1;}
}
}
